                                switch(status) {
                                        case TAG3:
                                                param->type = TAG_PARAM;
                                        case PARA_NAME:
                                        case TAG1:
                                        case TAG2:
                                                param->name.len = tmp - param->name.s;
                                                status = S_EQUAL;
                                        case S_EQUAL:
                                        case S_PARA_VALUE:
                                                saved_status = status;
                                                goto endofheader;
                                        case PARA_VALUE_TOKEN:
                                                status = E_PARA_VALUE;
                                                param->value.len = tmp - param->value.s;
                                                add_param(param, to_b, newparam);
                                        case E_PARA_VALUE:
                                                saved_status = status;
