                                break;
                        case '>':
                                switch(status) {
                                        case DISPLAY_QUOTED:
                                                break;
                                        case URI_ENCLOSED:
                                                to_b->uri.len = tmp - to_b->uri.s;
                                        case E_URI_ENCLOSED:
                                                status = END;
                                                foo = 0;
                                                break;
                                        case F_CRLF:
                                        case F_LF:
                                        case F_CR:
                                                /*previous=crlf and now !=' '*/
                                                goto endofheader;
                                        default:
                                                LM_ERR("unexpected char [%c] in status %d: [%.*s] .\n",
                                                                *tmp, status, (int)(tmp - buffer), ZSW(buffer));
                                                goto error;
                                }
                                break;
                        case '"':
                                switch(status) {
                                        case START_TO:
                                                to_b->body.s = tmp;
                                                to_b->display.s = tmp;
                                                status = DISPLAY_QUOTED;
                                                break;
                                        case DISPLAY_QUOTED:
                                                status = E_DISPLAY_QUOTED;
                                                to_b->display.len = tmp - to_b->display.s + 1;
                                                break;
                                        case F_CRLF:
                                        case F_LF:
